 "content": "def transform(grid):
    """Overlay two panels, marking cells occupied in both with color 2."""
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("grid must be rectangular")

    # Find a uniform nonzero separator row or column between equal-sized panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            top, bottom = grid[:r], grid[r + 1:]
            if top and len(top) == len(bottom):
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                        for ra, rb in zip(top, bottom)]
    for c in range(w):
        if len({row[c] for row in grid}) == 1 and grid[0][c] != 0:
            left_w, right_w = c, w - c - 1
            if left_w and left_w == right_w:
                return [[2 if row[i] != 0 and row[c + 1 + i] != 0 else 0
                         for i in range(left_w)] for row in grid]
    raise ValueError("expected one full-length nonzero separator between equal panels")

if __name__ == '__main__':
    import json, sys
